head.b:skin:
:root{--navy:#102f37;--ink:#16373e;--muted:#5b7174;--teal:#127777;--aqua:#b9eee0;--sand:#f7f8f3;--line:#dce3dd;--coral:#d9886d}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:105px}body{margin:0;color:var(--ink);background:#fff;font-family:'DM Sans',Arial,sans-serif;font-size:15px;line-height:1.75}button,input,select,textarea{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none;cursor:pointer}button{cursor:pointer}img{display:block;max-width:100%;object-fit:cover}button{color:inherit}h1,h2,h3,p{margin-top:0}h1,h2,h3{font-family:Manrope,Arial,sans-serif;font-weight:500;line-height:1.2;letter-spacing:-1.7px}h2{font-size:clamp(33px,3.6vw,48px);margin-bottom:24px}h2 em,h1 em{font-family:Georgia,serif;font-weight:400}h3{font-size:21px;letter-spacing:-.4px}p{color:var(--muted)}.wrap{width:min(1240px,calc(100% - 112px));margin-inline:auto}.section{padding-block:100px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2.5px;color:var(--teal);margin-bottom:22px}.eyebrow.light{color:var(--aqua)}.line{display:inline-block;width:32px;height:1px;background:currentColor;margin-right:12px;vertical-align:middle}.header{height:90px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;padding:0 42px;gap:28px;position:sticky;top:0;z-index:20;border-bottom:1px solid #ffffff18}.brand{display:block;flex-shrink:0}.brand img{object-fit:contain}.header nav{display:flex;gap:24px;align-items:center}.header nav a{font-size:11px;color:#e0e8e6;white-space:nowrap;position:relative}.header nav a:after{content:'';position:absolute;bottom:-8px;left:0;width:0;height:1px;background:var(--aqua);transition:width .2s}.header nav a:hover:after{width:100%}.button{border:1px solid var(--navy);display:inline-flex;align-items:center;justify-content:space-between;gap:30px;padding:15px 24px;background:var(--navy);color:white;font-size:12px;font-weight:600;line-height:1.5;transition:transform .2s,background .2s;min-height:48px}.button:hover{transform:translateY(-2px);background:#22545b}.button span{font-size:19px}.button.small{padding:10px 18px;min-height:43px;font-size:11px;gap:18px;background:var(--aqua);border-color:var(--aqua);color:var(--ink)}.button.aqua{background:var(--aqua);color:var(--ink);border-color:var(--aqua)}.button.aqua:hover{background:#92ddc9}.button.outline{background:transparent;color:var(--ink);border-color:#b6c8c3}.menu-toggle{display:none}.hero{height:740px;min-height:650px;position:relative;background:#073943;color:white;overflow:hidden}.hero-photo,.hero-shade{position:absolute;inset:0;width:100%;height:100%}.hero-photo{object-position:center 48%}.hero-shade{background:linear-gradient(90deg,rgba(5,35,44,.8),rgba(5,35,44,.35) 53%,rgba(5,35,44,.04)),linear-gradient(0deg,rgba(5,35,44,.5),transparent 35%)}.hero-content{position:relative;padding-top:83px}.hero h1{font-size:clamp(48px,5.5vw,78px);line-height:1.11;letter-spacing:-3px;max-width:760px;margin-bottom:28px}.hero h1 em{color:#bce6dd}.hero-description{color:#e0eae8;font-size:14px;line-height:1.9}.hero-actions{display:flex;gap:30px;align-items:center;margin-top:33px}.text-link{display:inline-flex;gap:30px;align-items:center;font-size:12px;font-weight:600;padding-block:12px;border-bottom:1px solid #86aaa2;color:var(--ink)}.text-link span{font-size:20px}.text-link.white{color:white;border-color:#ffffff50}.hero-bottom{position:absolute;bottom:39px;left:0;right:0;display:flex;justify-content:space-between;align-items:flex-end}.scroll-link{font-size:9px;letter-spacing:2px;display:flex;align-items:center;gap:16px}.scroll-icon{border:1px solid #ffffff60;border-radius:50%;height:38px;width:38px;display:grid;place-items:center;font-size:17px}.hero-note{text-align:right}.hero-note>span{font-size:9px;letter-spacing:2px;color:var(--aqua)}.hero-note p{color:white;font-size:12px;margin:8px 0 0}.image-disclaimer{position:absolute;right:12px;top:12px;font-size:8px;opacity:.65}.intro{display:grid;grid-template-columns:1.2fr 1fr;gap:100px;padding-top:80px;padding-bottom:40px;align-items:center}.intro h2{font-size:37px;margin:0}.intro>p{font-size:14px;margin:20px 0 0}.services{display:grid;grid-template-columns:repeat(5,1fr);padding-bottom:68px}.services>a{border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:14px;padding:25px 12px 25px 0;position:relative;font-size:11px;line-height:1.7}.services>a:hover{color:var(--teal);background:var(--sand)}.services b{margin-left:auto;font-size:17px;font-weight:400}.services strong{font-weight:600}.service-icon{font-size:31px;color:var(--teal);font-family:Georgia,serif}.adventures{background:var(--sand)}.section-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:40px;margin-bottom:36px}.section-heading h2{margin:0}.section-heading>p{font-size:13px;margin-bottom:6px;max-width:350px}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:38px 0 18px}.filters button{border:1px solid #d1ddd6;background:transparent;padding:10px 17px;border-radius:2px;font-size:11px;min-height:42px;transition:background .2s}.filters button.active,.filters button:hover{background:var(--navy);color:white;border-color:var(--navy)}.catalog-meta{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-bottom:20px}.package-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px}.package-card{border:1px solid #e0e6df;background:white;transition:transform .25s}.package-card:hover{transform:translateY(-5px)}.card-photo{position:relative;aspect-ratio:1.55;overflow:hidden;background:#145a65}.card-photo img{width:100%;height:100%;transition:transform .5s}.package-card:hover img{transform:scale(1.04)}.card-badge{position:absolute;top:16px;left:16px;background:#ffffffed;padding:4px 11px;font-size:9px;letter-spacing:.7px}.card-content{padding:23px}.card-location{color:var(--teal);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px}.card-content h3{font-size:21px;line-height:1.35;margin-bottom:12px}.card-content>p{font-size:12px;line-height:1.8;min-height:43px}.card-duration{display:block;font-size:10px;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:17px}.card-bottom{padding-top:17px;display:flex;justify-content:space-between;align-items:center;gap:8px}.card-bottom strong{font-size:11px;font-weight:500}.card-detail{border:1px solid #b6c8c3;background:transparent;border-radius:50%;width:40px;height:40px;font-size:22px;flex-shrink:0}.card-detail:hover{background:var(--aqua)}.more{margin:35px auto 0;display:flex;width:max-content}.price-note{font-size:11px;text-align:center;margin:16px 0 0}.training{display:grid;grid-template-columns:1fr 1fr;gap:90px;align-items:center}.photo-panel{height:570px;position:relative;background:#0d4f5c}.photo-panel img{height:100%;width:100%;object-position:70%}.photo-label{position:absolute;bottom:23px;left:22px;color:white;font-size:9px;letter-spacing:2px}.training>div>p:not(.eyebrow){font-size:13px}.training details{border-bottom:1px solid var(--line)}summary{list-style:none;cursor:pointer;min-height:59px;display:flex;align-items:center;gap:22px;font-size:13px;font-weight:500}summary::-webkit-details-marker{display:none}summary>span{color:var(--teal);font-size:10px}summary>b{margin-left:auto;font-size:23px;font-weight:400}details[open] summary>b{transform:rotate(45deg)}details p{font-size:12px;padding:0 12px 12px 0;margin:0}.training .text-link{margin-top:25px}.conservation{padding:95px 0;background:var(--navy);color:white}.conservation-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:130px;align-items:center}.conservation h2 em{color:var(--aqua)}.conservation p{color:#bfd0ce;font-size:13px}.conservation .button{margin-top:16px}.conservation-list>div{border-bottom:1px solid #ffffff25;padding:23px 0 20px 46px;position:relative}.conservation-list>div:first-child{padding-top:0}.conservation-list span{position:absolute;left:0;color:var(--aqua);font-size:10px}.conservation-list h3{font-size:18px;margin-bottom:12px}.conservation-list p{margin-bottom:0;font-size:12px}.consultancy{display:grid;grid-template-columns:1fr 1fr;gap:110px;align-items:center}.consultancy>div>p:not(.eyebrow){font-size:13px}.consult-topics h3{font-size:13px;margin-bottom:23px}.consult-topics>p{padding:17px 0;border-bottom:1px solid var(--line);margin:0;font-size:13px;display:flex;gap:20px;color:var(--ink)}.consult-topics p>span{font-size:10px;color:var(--teal)}.consult-topics b{margin-left:auto;font-weight:400}.consult-topics small{display:block;margin-top:20px;font-size:10px;color:var(--muted)}.about{background:#eaf1eb}.about-grid{display:grid;grid-template-columns:1fr 2fr;gap:80px}.about-grid>.eyebrow{margin-top:12px}.about-grid p:not(.eyebrow){max-width:740px;font-size:14px}.gallery{display:grid;grid-template-columns:1.6fr 1fr 1fr;gap:20px}.gallery button{border:0;background:var(--navy);padding:0;position:relative;overflow:hidden;height:340px;text-align:left}.gallery img{height:100%;width:100%;transition:transform .5s}.gallery button:hover img{transform:scale(1.05)}.gallery button:after{content:'';position:absolute;inset:40% 0 0;background:linear-gradient(transparent,#071f29c0)}.gallery button span{position:absolute;bottom:20px;left:22px;right:22px;color:white;font-size:11px;z-index:1}.gallery b{float:right;font-size:20px;font-weight:400}.faq{background:var(--sand)}.faq-grid{display:grid;grid-template-columns:1fr 1.65fr;gap:110px}.faq-grid>div>p:not(.eyebrow){font-size:13px}.faq details{border-bottom:1px solid #d4dfd6}.faq summary{font-size:13px;padding-block:12px;min-height:67px}.faq details p{padding-right:25px;font-size:13px}.contact{display:grid;grid-template-columns:1fr 1.1fr;gap:110px}.contact>div>p:not(.eyebrow){font-size:13px;max-width:370px}.contact-link{display:block;font-size:16px;margin:26px 0}.contact-link>span{display:block;font-size:9px;color:var(--teal);letter-spacing:1.5px;margin-bottom:4px}.contact .fine-print{font-size:11px!important;margin-top:30px;max-width:340px}form{padding:30px;background:var(--sand);align-self:start}label{font-size:11px;display:block;margin-bottom:18px;font-weight:500}label>span{color:#a15340}input,select,textarea{border:1px solid #c9d5ce;background:#fff;border-radius:0;width:100%;padding:12px;font-size:12px;color:var(--ink);display:block;margin-top:7px;min-height:46px}textarea{resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}form .button{width:100%}.form-alternative{display:block;text-align:center;font-size:10px;margin-top:16px;text-decoration:underline;text-underline-offset:4px}#form-status{font-size:12px;line-height:1.7;margin:12px 0 0}footer{background:var(--navy);color:#d5e2de;padding:65px 0 0}.footer-grid{display:grid;grid-template-columns:1.6fr 1fr 1.2fr 1.1fr;gap:50px;padding-bottom:50px}.footer-grid h3{color:white;font-size:12px;letter-spacing:0;margin-bottom:24px}.footer-grid a:not(.brand){display:block;font-size:11px;margin:10px 0}.footer-grid p{font-size:11px;color:#b4c9c5;margin-top:20px}.footer-bottom{border-top:1px solid #ffffff25;display:flex;justify-content:space-between;gap:25px;padding:24px 0;font-size:9px}.floating-wa{position:fixed;bottom:24px;right:24px;background:var(--aqua);color:var(--navy);display:flex;align-items:center;gap:8px;padding:13px 18px;border:1px solid #85bfad;border-radius:30px;z-index:18;box-shadow:0 4px 20px #102f3720;font-size:11px}.floating-wa svg{width:23px;fill:none;stroke:currentColor;stroke-width:1.5}dialog{border:0;padding:38px;max-width:620px;width:calc(100% - 32px);max-height:85vh;color:var(--ink);box-shadow:0 20px 90px #0004}dialog::backdrop{background:#06232bd9;backdrop-filter:blur(4px)}.dialog-close{position:sticky;top:0;float:right;width:42px;height:42px;border:1px solid var(--line);background:white;font-size:27px;z-index:1}dialog h2{font-size:32px;clear:both;padding-top:12px}dialog h3{font-size:16px}dialog p,dialog li{font-size:13px}dialog ul{padding-left:18px}#gallery-dialog{max-width:1100px;background:var(--navy);color:white;padding:15px}#gallery-image{width:100%;max-height:68vh;object-fit:contain}#gallery-caption{color:white;margin:15px}.skip{position:fixed;top:-100px;background:white;padding:14px;z-index:50}.skip:focus{top:10px}:focus-visible{outline:3px solid #c77951;outline-offset:5px}body:has(dialog[open]){overflow:hidden}[hidden]{display:none!important}.image-failed{object-fit:contain;background:#145a65;color:white;font-size:12px;padding:20px}.noscript{padding:20px}.form-invalid{border-color:#a15340}
@media(min-width:1550px){.hero{height:790px}.hero-content{padding-top:100px}}@media(max-width:1200px){.header{padding-inline:28px;gap:20px}.header nav{gap:15px}.header nav a{font-size:10px}.header .brand img{width:195px}.header-cta{gap:10px!important}.wrap{width:calc(100% - 72px)}.training,.consultancy,.conservation-grid,.contact{gap:55px}.services>a{gap:8px}.service-icon{font-size:25px}.hero h1{font-size:68px}}@media(max-width:1000px){.header{height:78px}.header .header-cta{margin-left:auto}.menu-toggle{display:block;order:3;color:white;background:transparent;border:1px solid #ffffff50;font-size:22px;width:44px;height:44px}.header nav{display:none;position:absolute;top:78px;left:0;right:0;background:var(--navy);padding:20px 36px 30px;box-shadow:0 10px 20px #0002}.header nav.open{display:flex;flex-direction:column;align-items:stretch;gap:0}.header nav a{padding:13px;font-size:13px;border-bottom:1px solid #ffffff20}.intro{gap:40px}.intro h2{font-size:31px}.services{grid-template-columns:repeat(3,1fr)}.package-grid{gap:18px}.card-content{padding:18px}.card-content h3{font-size:19px}.section{padding-block:75px}.training{gap:40px}.photo-panel{height:520px}.faq-grid{gap:50px}.footer-grid{gap:30px;grid-template-columns:1.5fr 1fr 1fr}.footer-grid>div:last-child{grid-column:1/-1}.footer-grid>div:last-child>a{display:inline-block;margin-right:20px}.gallery button{height:280px}}@media(max-width:700px){.wrap{width:calc(100% - 40px)}.header{padding-inline:20px;gap:12px}.header .brand img{width:185px}.header .header-cta{display:none}.menu-toggle{margin-left:auto}.hero{height:740px;min-height:0}.hero-photo{object-position:64% center}.hero-shade{background:linear-gradient(90deg,#05232cce,#05232c40),linear-gradient(0deg,#05232c99,transparent)}.hero-content{padding-top:75px}.hero .eyebrow{font-size:8px;letter-spacing:1.5px}.hero h1{font-size:clamp(44px,10vw,67px);letter-spacing:-2px}.hero-description{font-size:12px}.hero-actions{align-items:flex-start;flex-direction:column;gap:12px;margin-top:26px}.hero-bottom{bottom:40px}.hero-note{max-width:150px}.hero-note>span{font-size:7px;letter-spacing:1px}.hero-note p{font-size:10px}.scroll-link{font-size:7px;gap:8px;letter-spacing:1px}.image-disclaimer{font-size:7px}.intro{grid-template-columns:1fr;gap:18px;padding-top:55px;padding-bottom:30px}.intro h2{font-size:32px}.intro>p{margin-top:0}.services{grid-template-columns:1fr 1fr;padding-bottom:45px}.services>a{padding:20px 10px 20px 0}.services>a:last-child{grid-column:1/-1}.section{padding-block:60px}h2{font-size:33px;letter-spacing:-1px}.section-heading{display:block;margin-bottom:25px}.section-heading>p{margin-top:20px}.filters{gap:7px;margin-top:28px}.filters button{padding:8px 12px;font-size:10px}.catalog-meta{gap:15px;font-size:9px}.catalog-meta>span:last-child{max-width:160px;text-align:right}.package-grid{grid-template-columns:1fr;gap:24px}.card-photo{aspect-ratio:1.65}.card-content{padding:23px}.card-content h3{font-size:23px}.card-content>p{min-height:0}.training,.conservation-grid,.consultancy,.about-grid,.faq-grid,.contact{grid-template-columns:1fr;gap:35px}.photo-panel{height:380px}.conservation{padding-block:60px}.conservation-list>div:first-child{padding-top:20px}.about-grid{gap:5px}.gallery{grid-template-columns:1fr 1fr;gap:12px}.gallery button:first-child{grid-column:1/-1;height:270px}.gallery button{height:230px}.gallery button span{font-size:10px;left:13px;right:13px}.footer-grid{grid-template-columns:1fr 1fr;gap:35px 22px}.footer-grid>div:first-child,.footer-grid>div:last-child{grid-column:1/-1}.footer-bottom{flex-wrap:wrap;padding-bottom:100px;gap:12px}.footer-bottom>span:nth-child(2){display:none}.floating-wa{bottom:16px;right:16px;padding:12px}.floating-wa>span{display:none}form{padding:22px}.form-row{gap:12px}.form-row label{min-width:0}input[type=date]{min-width:0}dialog{padding:25px}.contact .fine-print{max-width:none}.hero .button{padding-inline:20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important;animation:none!important}}

.arrow-icon{width:18px;height:18px;display:inline-block;vertical-align:middle;fill:none;stroke:currentColor;stroke-width:1.4;flex-shrink:0}.card-detail .arrow-icon{width:20px;height:20px}.gallery b .arrow-icon{width:18px;height:18px}

